import "server-only";
import { AuthorizationError, ResourceNotFoundError } from "@formbricks/types/errors";
import { getV3AuthorizationActor } from "@/app/api/v3/lib/auth";
import { problemForbidden, problemUnauthorized, successResponse } from "@/app/api/v3/lib/response";
import type { TV3AuditLog, TV3Authentication } from "@/app/api/v3/lib/types";
import { assertCan } from "@/lib/authorization";
import { getOrganizationIdFromApiKeyId } from "@/lib/utils/helper";
import { rotateApiKey } from "@/modules/organization/settings/api-keys/lib/api-key";

type TBaseParams = {
  authentication: TV3Authentication;
  requestId: string;
  instance?: string;
};

/**
 * Replaces the secret of an API key and returns the new plaintext once.
 *
 * Session-only: a key must not be able to mint a fresh credential for itself or another key. The
 * organization is resolved from the key, never from the request, and the check is the one
 * `updateApiKeyAction` and `deleteApiKeyAction` ask. An unknown key answers 403, not 404, so a signed-in
 * user cannot probe API key ids across the instance.
 */
export async function rotateV3ApiKey(
  params: TBaseParams & { apiKeyId: string; auditLog?: TV3AuditLog }
): Promise<Response> {
  const { authentication, apiKeyId, auditLog, requestId, instance } = params;

  const actor = getV3AuthorizationActor(authentication);
  if (actor?.type !== "user") {
    return problemUnauthorized(requestId, "Session required", instance);
  }

  let organizationId: string;
  try {
    organizationId = await getOrganizationIdFromApiKeyId(apiKeyId);
    await assertCan(actor, "apiKey.manage", { type: "apiKey", id: apiKeyId });
  } catch (error) {
    if (error instanceof ResourceNotFoundError || error instanceof AuthorizationError) {
      return problemForbidden(requestId, "You are not authorized to access this resource", instance);
    }
    throw error;
  }

  if (auditLog) {
    auditLog.organizationId = organizationId;
    auditLog.targetId = apiKeyId;
    auditLog.apiKeyId = apiKeyId;
  }

  const { before, after } = await rotateApiKey(apiKeyId);

  if (auditLog) {
    // Neither side carries a hash or the plaintext secret: only what the key is, never what it was.
    auditLog.oldObject = { id: before.id, label: before.label, lastUsedAt: before.lastUsedAt };
    auditLog.newObject = { id: after.id, label: after.label, rotated: true };
  }

  return successResponse(
    {
      id: after.id,
      label: after.label,
      createdAt: after.createdAt.toISOString(),
      lastUsedAt: after.lastUsedAt ? after.lastUsedAt.toISOString() : null,
      apiKey: after.actualKey,
    },
    { requestId, cache: "no-store" }
  );
}
EOF
